<?php
require_once __DIR__.'/includes/auth.php';$u=require_login();$vid=filter_input(INPUT_GET,'version',FILTER_VALIDATE_INT);if(!$vid){http_response_code(404);exit('Document not found.');}$q=db()->prepare('SELECT v.*,s.project_id,s.document_type,s.status submission_status FROM submission_versions v JOIN submissions s ON s.id=v.submission_id WHERE v.id=?');$q->execute([$vid]);$v=$q->fetch();if(!$v||!project_access((int)$v['project_id'],$u)){http_response_code(404);exit('Document not found.');}if($u['role']==='examiner'&&($v['document_type']!=='final_project'||$v['submission_status']!=='approved')){http_response_code(404);exit('Document not found.');}if(!preg_match('~^\d{4}/\d+/[a-f0-9]{48}\.(pdf|doc|docx)$~D',$v['storage_path'])){http_response_code(404);exit('Document not found.');}$path=UPLOAD_ROOT.DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$v['storage_path']);if(!is_file($path)){http_response_code(404);exit('Document not found.');}header('Content-Type: '.$v['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.rawurlencode($v['original_filename']).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;
